/**
 * @method
 * @name bitvavo#watchOrderBookForSymbols
 * @description watches information on open orders with bid (buy) and ask (sell) prices, volumes and other data for multiple markets
 * @see https://docs.bitvavo.com/docs/websocket-api/book-subscription/
 * @param {string[]} symbols unified symbols of the markets to fetch the order book for
 * @param {int} [limit] the maximum amount of order book entries to return
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [order book structure]{@link https://docs.ccxt.com/?id=order-book-structure}
 */
func (this *Bitvavo) WatchOrderBookForSymbolsAsync(symbols any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchOrderBookForSymbolsBody(ch, symbols, optionalArgs...)
	return ch
}
func (this *Bitvavo) watchOrderBookForSymbolsBody(ch chan any, symbols any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	symbols = this.MarketSymbols(symbols, nil, false)
	var name string = "book"
	var marketIds []any = []any{}
	var messageHashes []any = []any{}
	for i := 0; i < ccxt.GetArrayLength(symbols); i++ {
		var market map[string]any = ccxt.MapTyped(this.Market(ccxt.GetValue(symbols, i)))
		marketIds = append(marketIds, market["id"])
		messageHashes = append(messageHashes, ccxt.Add(name+"@", market["id"]))
	}
	var url any = ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws")
	var request map[string]any = map[string]any{
		"action": "subscribe",
		"channels": []any{map[string]any{
			"name":    name,
			"markets": marketIds,
		}},
	}
	// the per-market snapshot machinery reads the marketId from the buffered
	// delta messages, so the shared subscription only carries the common fields
	var subscription map[string]any = map[string]any{
		"name":    name,
		"symbols": symbols,
		"limit":   limit,
		"params":  params,
	}
	var message map[string]any = this.Extend(request, params)

	var orderbook ccxt.OrderBookInterface = ccxt.PanicOnError((<-this.WatchMultiple(url, messageHashes, message, messageHashes, subscription))).(ccxt.OrderBookInterface)

	ch <- orderbook.(ccxt.OrderBookInterface).Limit()
	return nil
}

