func (this *Bitvavo) HandleDelta(bookside any, delta any) {
	var price *float64 = this.SafeFloat(delta, 0)
	var amount *float64 = this.SafeFloat(delta, 1)
	bookside.(ccxt.IOrderBookSide).Store(price, amount)
}
func (this *Bitvavo) HandleDeltas(bookside any, deltas any) {
	for i := 0; i < ccxt.GetArrayLength(deltas); i++ {
		this.HandleDelta(bookside, ccxt.GetValue(deltas, i))
	}
}
func (this *Bitvavo) HandleOrderBookMessage(client any, message any, orderbook any) any {
	//
	//     {
	//         "event": "book",
	//         "market": "BTC-EUR",
	//         "nonce": 36947383,
	//         "bids": [
	//             [ "8477.8", "0" ]
	//         ],
	//         "asks": [
	//             [ "8550.9", "0" ]
	//         ]
	//     }
	//
	var nonce *int64 = this.SafeInteger(message, "nonce")
	if ccxt.IsGreaterThan(nonce, ccxt.GetValue(orderbook, "nonce")) {
		this.HandleDeltas(ccxt.GetValue(orderbook, "asks"), this.SafeList(message, "asks", []any{}))
		this.HandleDeltas(ccxt.GetValue(orderbook, "bids"), this.SafeList(message, "bids", []any{}))
		ccxt.AddElementToObject(orderbook, "nonce", nonce)
	}
	return orderbook
}
func (this *Bitvavo) HandleOrderBook(client any, message map[string]any) {
	//
	//     {
	//         "event": "book",
	//         "market": "BTC-EUR",
	//         "nonce": 36729561,
	//         "bids": [
	//             [ "8513.3", "0" ],
	//             [ '8518.8', "0.64236203" ],
	//             [ '8513.6', "0.32435481" ],
	//         ],
	//         "asks": []
	//     }
	//
	var event *string = this.SafeString(message, "event")
	var marketId *string = this.SafeString(message, "market")
	var market map[string]any = ccxt.MapTyped(this.SafeMarket(marketId, nil, "-"))
	var symbol *string = ccxt.SafeStringPtr(market["symbol"])
	var messageHash any = ccxt.Add(ccxt.Add(event, "@"), market["id"])
	var orderbook any = this.SafeValue(this.Orderbooks, symbol)
	if ccxt.IsEqual(orderbook, nil) {
		return
	}
	if ccxt.IsEqual(ccxt.GetValue(orderbook, "nonce"), nil) {
		var subscription any = this.SafeValue(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash, map[string]any{})
		// multi-symbol watches share one subscription object, so the
		// snapshot-in-flight flag must be tracked per market
		var flagKey any = ccxt.Add("watchingOrderBookSnapshot@", marketId)
		var watchingOrderBookSnapshot *bool = this.SafeBool(subscription, flagKey)
		if watchingOrderBookSnapshot == nil {
			ccxt.AddElementToObject(subscription, flagKey, true)
			ccxt.AddElementToObject(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash, subscription)
			var options map[string]any = ccxt.SafeMapTyped(this.Options, "watchOrderBookSnapshot")
			var delay *int64 = this.SafeInteger(options, "delay", this.RateLimit)
			// fetch the snapshot in a separate async call after a warmup delay
			this.Delay(delay, this.WatchOrderBookSnapshotAsync, client, message, subscription)
		}
		ccxt.AppendToArray(orderbook.(ccxt.OrderBookInterface).GetCache(), message)
	} else {
		this.HandleOrderBookMessage(client, message, orderbook)
		client.(ccxt.ClientInterface).Resolve(orderbook, messageHash)
	}
}
func (this *Bitvavo) WatchOrderBookSnapshotAsync(client any, message any, subscription any) <-chan any {
	ch := make(chan any, 1)
	go this.watchOrderBookSnapshotBody(ch, client, message, subscription)
	return ch
}
func (this *Bitvavo) watchOrderBookSnapshotBody(ch chan any, client any, message any, subscription any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params any = this.SafeDict(subscription, "params")
	// multi-symbol watches share one subscription object without a marketId,
	// in that case the buffered delta message identifies the market
	var marketId *string = this.SafeString2(subscription, "marketId", "market", this.SafeString(message, "market"))
	var snapshotSymbol *string = this.SafeSymbol(marketId, nil, "-")
	if !(ccxt.InOp(this.Orderbooks, snapshotSymbol)) {

		// this snapshot fetch was scheduled before an unsubscribe removed the
		// order book - skip it so the getBook request is not sent for a dead market
		return nil
	}
	var name string = "getBook"
	var messageHash any = ccxt.Add(name+"@", marketId)
	var url any = ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws")
	var request map[string]any = map[string]any{
		"action": name,
		"market": marketId,
	}

	var orderbook ccxt.OrderBookInterface = ccxt.PanicOnError((<-this.Watch(url, messageHash, this.Extend(request, params), messageHash, subscription))).(ccxt.OrderBookInterface)

	ch <- orderbook.(ccxt.OrderBookInterface).Limit()
	return nil
}
func (this *Bitvavo) HandleOrderBookSnapshot(client any, message map[string]any) {
	//
	//     {
	//         "action": "getBook",
	//         "response": {
	//             "market": "BTC-EUR",
	//             "nonce": 36946120,
	//             "bids": [
	//                 [ '8494.9', "0.24399521" ],
	//                 [ '8494.8', "0.34884085" ],
	//                 [ '8493.9', "0.14535128" ],
	//             ],
	//             "asks": [
	//                 [ "8495", "0.46982463" ],
	//                 [ '8495.1', "0.12178267" ],
	//                 [ '8496.2', "0.21924143" ],
	//             ]
	//         }
	//     }
	//
	var response any = this.SafeDict(message, "response")
	if ccxt.IsEqual(response, nil) {
		return
	}
	var marketId *string = this.SafeString(response, "market")
	var symbol *string = this.SafeSymbol(marketId, nil, "-")
	var name string = "book"
	var messageHash any = ccxt.Add(name+"@", marketId)
	var orderbook any = this.SafeValue(this.Orderbooks, symbol)
	if ccxt.IsEqual(orderbook, nil) {
		// the market was unsubscribed while this snapshot request was in flight
		return
	}
	var snapshot map[string]any = this.ParseOrderBook(response, symbol)
	snapshot["nonce"] = this.SafeInteger(response, "nonce")
	orderbook.(ccxt.OrderBookInterface).Reset(snapshot)
	// unroll the accumulated deltas
	var messages any = orderbook.(ccxt.OrderBookInterface).GetCache()
	for i := 0; i < ccxt.GetArrayLength(messages); i++ {
		var messageItem any = ccxt.GetValue(messages, i)
		this.HandleOrderBookMessage(client, messageItem, orderbook)
	}
	ccxt.AddElementToObject(this.Orderbooks, symbol, orderbook)
	client.(ccxt.ClientInterface).Resolve(orderbook, messageHash)
	// getBook is a one-shot request but this.watch tracks it as a persistent
	// subscription - drop it so a later unsubscribe/subscribe re-fetches the snapshot
	// instead of suppressing the request as an already-active subscription
	var snapshotHash any = ccxt.Add("getBook@", marketId)
	if ccxt.InOp(client.(ccxt.ClientInterface).GetSubscriptions(), snapshotHash) {
		ccxt.Remove(client.(ccxt.ClientInterface).GetSubscriptions(), snapshotHash)
	}
}
func (this *Bitvavo) HandleOrderBookSubscription(client any, message map[string]any, subscription map[string]any) {
	var symbol *string = this.SafeString(subscription, "symbol")
	var limit *int64 = this.SafeInteger(subscription, "limit")
	if ccxt.InOp(this.Orderbooks, symbol) {
		ccxt.Remove(this.Orderbooks, symbol)
	}
	ccxt.AddElementToObject(this.Orderbooks, symbol, this.OrderBook(map[string]any{}, limit))
}
func (this *Bitvavo) HandleOrderBookSubscriptions(client any, message map[string]any, marketIds []any) {
	var name string = "book"
	for i := 0; i < len(marketIds); i++ {
		var marketId *string = this.SafeString(marketIds, i)
		var symbol *string = this.SafeSymbol(marketId, nil, "-")
		var messageHash any = ccxt.Add(name+"@", marketId)
		if !(ccxt.InOp(this.Orderbooks, symbol)) {
			var subscription any = this.SafeValue(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash)
			var method any = this.SafeValue(subscription, "method")
			if !ccxt.IsEqual(method, nil) {
				ccxt.CallDynamically(method, client, message, subscription)
			} else if !ccxt.IsEqual(subscription, nil) {
				// multi-symbol watches share one subscription object without a
				// per-market method - initialize the order book directly
				var limit *int64 = this.SafeInteger(subscription, "limit")
				ccxt.AddElementToObject(this.Orderbooks, symbol, this.OrderBook(map[string]any{}, limit))
			}
		}
	}
}
func (this *Bitvavo) UnWatchChannelsAsync(topic any, channels any, subMessageHashes any, subscriptionArgs any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.unWatchChannelsBody(ch, topic, channels, subMessageHashes, subscriptionArgs, optionalArgs...)
	return ch
}
func (this *Bitvavo) unWatchChannelsBody(ch chan any, topic any, channels any, subMessageHashes any, subscriptionArgs any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var url any = ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws")
	var request map[string]any = map[string]any{
		"action":   "unsubscribe",
		"channels": channels,
	}
	var unsubHashes []any = []any{}
	for i := 0; i < ccxt.GetArrayLength(subMessageHashes); i++ {
		unsubHashes = append(unsubHashes, ccxt.Add("unsubscribe:", ccxt.GetValue(subMessageHashes, i)))
	}
	var subscription map[string]any = this.Extend(map[string]any{
		"topic":            topic,
		"subMessageHashes": subMessageHashes,
		"unsubHashes":      unsubHashes,
	}, subscriptionArgs)
	var message map[string]any = this.Extend(request, params)

	ch <- ccxt.PanicOnError((<-this.WatchMultiple(url, unsubHashes, message, unsubHashes, subscription)))
	return nil
}
func (this *Bitvavo) HandleUnsubscriptionStatus(client any, message map[string]any) any {
	//
	//     {
	//         "event": "unsubscribed",
	//         "subscriptions": {}
	//     }
	//
	// the confirmation carries the remaining subscriptions without identifying
	// which unsubscribe request it belongs to, so settle every pending unsubscription
	var keys []string = ccxt.ObjectKeys(client.(ccxt.ClientInterface).GetSubscriptions())
	for i := 0; i < len(keys); i++ {
		var key string = ccxt.GetValue(keys, i).(string)
		if !(ccxt.InOp(client.(ccxt.ClientInterface).GetSubscriptions(), key)) {
			continue
		}
		if !strings.HasPrefix(key, "unsubscribe:") {
			continue
		}
		var subscription any = ccxt.GetValue(client.(ccxt.ClientInterface).GetSubscriptions(), key)
		var subHash string = strings.Replace(key, "unsubscribe:", "", 1)
		this.CleanCache(subscription)
		this.CleanUnsubscription(ccxt.AsClient(client), subHash, key)
		// bitvavo resolves-and-deletes the data futures on every message, so at
		// unsubscribe time the sub future is usually already gone and cleanUnsubscription
		// stashes the error in client.rejections instead - that stale entry
		// would immediately reject the next subscribe's fresh future, so clear it here
		if ccxt.InOp(client.(ccxt.ClientInterface).GetRejections(), subHash) {
			ccxt.Remove(client.(ccxt.ClientInterface).GetRejections(), subHash)
		}
	}
	return message
}

/**
 * @method
 * @name bitvavo#watchOrders
 * @description watches information on multiple orders made by the user
 * @param {string} symbol unified market symbol of the market orders were made in
 * @param {int} [since] the earliest time in ms to fetch orders for
 * @param {int} [limit] the maximum number of order structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [order structures]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Bitvavo) WatchOrdersAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchOrdersBody(ch, optionalArgs...)
	return ch
}
func (this *Bitvavo) watchOrdersBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	symbol := ccxt.GetArg(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	limit := ccxt.GetArg(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if symbol == nil {
		panic(ccxt.ArgumentsRequired(this.Id + " watchOrders() requires a symbol argument"))
	}
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}

	ccxt.PanicOnError((<-this.AuthenticateAsync()))
	var market map[string]any = ccxt.MapTyped(this.Market(symbol))
	symbol = market["symbol"]
	var marketId *string = ccxt.SafeStringPtr(market["id"])
	var url any = ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws")
	var name string = "account"
	var messageHash any = ccxt.Add("order:", symbol)
	var request map[string]any = map[string]any{
		"action": "subscribe",
		"channels": []any{map[string]any{
			"name":    name,
			"markets": []any{marketId},
		}},
	}

	var orders ccxt.ArrayCacheInterface = ccxt.AsArrayCache(ccxt.PanicOnError((<-this.Watch(url, messageHash, request, messageHash))))
	if this.NewUpdates {
		limit = ccxt.ToGetsLimit(orders).GetLimit(symbol, limit)
	}

	ch <- this.FilterBySymbolSinceLimit(orders, symbol, since, limit, true)
	return nil
}

