	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	var tagparamsVariable []any = this.HandleWithdrawTagAndParams(tag, params)
	tag = ccxt.GetValue(tagparamsVariable, 0)
