func (this *Bitvavo) BuildMessageHash(action any, optionalArgs ...any) any {
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var methods map[string]any = map[string]any{
		"privateCreateOrder": this.ActionAndMarketMessageHash,
		"privateUpdateOrder": this.ActionAndOrderIdMessageHash,
		"privateCancelOrder": this.ActionAndOrderIdMessageHash,
		"privateGetOrder":    this.ActionAndOrderIdMessageHash,
		"privateGetTrades":   this.ActionAndMarketMessageHash,
	}
	var method any = this.SafeValue(methods, action)
	var messageHash any = action
	if !ccxt.IsEqual(method, nil) {
		messageHash = ccxt.CallDynamically(method, action, params)
	}
	return messageHash
}
func (this *Bitvavo) ActionAndMarketMessageHash(action any, optionalArgs ...any) any {
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var symbol *string = this.SafeString(params, "market", "")
	return ccxt.Add(action, symbol)
}
func (this *Bitvavo) ActionAndOrderIdMessageHash(action any, optionalArgs ...any) any {
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var orderId *string = this.SafeString(params, "orderId")
	if orderId == nil {
		panic(ccxt.ExchangeError(this.Id + " privateUpdateOrderMessageHash requires a orderId parameter"))
	}
	return ccxt.Add(action, orderId)
}
func (this *Bitvavo) HandleOrder(client any, message map[string]any) {
	//
	//     {
	//         "event": "order",
	//         "orderId": "f0e5180f-9497-4d05-9dc2-7056e8a2de9b",
	//         "market": "ETH-EUR",
	//         "created": 1590948500319,
	//         "updated": 1590948500319,
	//         "status": "new",
	//         "side": "sell",
	//         "orderType": "limit",
	//         "amount": "0.1",
	//         "amountRemaining": "0.1",
	//         "price": "300",
	//         "onHold": "0.1",
	//         "onHoldCurrency": "ETH",
	//         "selfTradePrevention": "decrementAndCancel",
	//         "visible": true,
	//         "timeInForce": "GTC",
	//         "postOnly": false
	//     }
	//
	var marketId *string = this.SafeString(message, "market")
	var market map[string]any = ccxt.MapTyped(this.SafeMarket(marketId, nil, "-"))
	var symbol *string = ccxt.SafeStringPtr(market["symbol"])
	var messageHash string = "order:" + *symbol
	var order map[string]any = ccxt.MapTyped(this.ParseOrder(message, market))
	if ccxt.IsEqual(this.Orders, nil) {
		var limit *int64 = this.SafeInteger(this.Options, "ordersLimit", 1000)
		this.Orders = ccxt.NewArrayCacheBySymbolById(limit)
	}
	var orders any = this.Orders
	orders.(ccxt.Appender).Append(order)
	client.(ccxt.ClientInterface).Resolve(this.Orders, messageHash)
}
func (this *Bitvavo) HandleMyTrade(client any, message map[string]any) {
	//
	//     {
	//         "event": "fill",
	//         "timestamp": 1590964470132,
	//         "market": "ETH-EUR",
	//         "orderId": "85d082e1-eda4-4209-9580-248281a29a9a",
	//         "fillId": "861d2da5-aa93-475c-8d9a-dce431bd4211",
	//         "side": "sell",
	//         "amount": "0.1",
	//         "price": "211.46",
	//         "taker": true,
	//         "fee": "0.056",
	//         "feeCurrency": "EUR"
	//     }
	//
	var marketId *string = this.SafeString(message, "market")
	var market map[string]any = ccxt.MapTyped(this.SafeMarket(marketId, nil, "-"))
	var symbol *string = ccxt.SafeStringPtr(market["symbol"])
	var messageHash string = "myTrades:" + *symbol
	var trade map[string]any = ccxt.MapTyped(this.ParseTrade(message, market))
	if ccxt.IsEqual(this.MyTrades, nil) {
		var limit *int64 = this.SafeInteger(this.Options, "tradesLimit", 1000)
		this.MyTrades = ccxt.NewArrayCache(limit)
	}
	var tradesArray any = this.MyTrades
	tradesArray.(ccxt.Appender).Append(trade)
	client.(ccxt.ClientInterface).Resolve(tradesArray, messageHash)
}
func (this *Bitvavo) HandleSubscriptionStatus(client any, message map[string]any) any {
	//
	//     {
	//         "event": "subscribed",
	//         "subscriptions": {
	//             "book": [ "BTC-EUR" ]
	//         }
	//     }
	//
	var subscriptions map[string]any = ccxt.SafeMapTyped(message, "subscriptions")
	var methods map[string]any = map[string]any{
		"book": this.HandleOrderBookSubscriptions,
	}
	var names []string = ccxt.ObjectKeys(subscriptions)
	for i := 0; i < len(names); i++ {
		var name string = ccxt.GetValue(names, i).(string)
		var method any = this.SafeValue(methods, name)
		if !ccxt.IsEqual(method, nil) {
			var subscription any = this.SafeValue(subscriptions, name)
			ccxt.CallDynamically(method, client, message, subscription)
		}
	}
	return message
}
func (this *Bitvavo) AuthenticateAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.authenticateBody(ch, optionalArgs...)
	return ch
}
func (this *Bitvavo) authenticateBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var url any = ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws")
	var client ccxt.ClientInterface = this.Client(url)
	var messageHash string = "authenticated"
	var future any = this.SafeValue(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash)
	if ccxt.IsEqual(future, nil) {
		var timestamp int64 = this.Milliseconds()
		var stringTimestamp string = ccxt.ToString(timestamp)
		var auth string = stringTimestamp + "GET/" + this.Version + "/websocket"
		var signature string = this.Hmac(this.Encode(auth), this.Encode(this.Secret), ccxt.Sha256)
		var action string = "authenticate"
		var request map[string]any = map[string]any{
			"action":    action,
			"key":       this.ApiKey,
			"signature": signature,
			"timestamp": timestamp,
		}
		var message map[string]any = this.Extend(request, params)

		future = (<-this.Watch(url, messageHash, message, messageHash))
		ccxt.PanicOnError(future)
		ccxt.AddElementToObject(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash, future)
	}

	ch <- future
	return nil
}
func (this *Bitvavo) HandleAuthenticationMessage(client any, message map[string]any) {
	//
	//     {
	//         "event": "authenticate",
	//         "authenticated": true
	//     }
	//
	var messageHash string = "authenticated"
	var authenticated *bool = this.SafeBool(message, "authenticated", false)
	if authenticated != nil && *authenticated == true {
		// we resolve the future here permanently so authentication only happens once
		client.(ccxt.ClientInterface).Resolve(message, messageHash)
	} else {
		error := ccxt.AuthenticationError(this.Json(message))
		client.(ccxt.ClientInterface).Reject(error, messageHash)
		// allows further authentication attempts
		if ccxt.InOp(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash) {
			ccxt.Remove(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash)
		}
	}
}
func (this *Bitvavo) HandleErrorMessage(client any, message any) any {
	//
	//    {
	//        action: 'privateCreateOrder',
	//        market: 'BTC-EUR',
	//        errorCode: 217,
	//        error: 'Minimum order size in quote currency is 5 EUR or 0.001 BTC.'
	//    }
	//    {
	//        action: 'privateCreateOrder',
	//        requestId: '17317539426571916',
	//        market: 'USDT-EUR',
	//        errorCode: 216,
	//        error: 'You do not have sufficient balance to complete this operation.'
	//    }
	//
	var error *string = this.SafeString(message, "error")
	var code *int64 = this.SafeInteger(error, "errorCode")
	var action *string = this.SafeString(message, "action")
	var buildMessage any = this.BuildMessageHash(action, message)
	var messageHash *string = this.SafeString(message, "requestId", buildMessage)
	var rejected bool = false

	{
		func(this *Bitvavo) (ret_ any) {
			defer func() {
				if e := recover(); e != nil {
					if e == "break" {
						return
					}
					ret_ = func(this *Bitvavo) any {
						// catch block:
						rejected = true
						client.(ccxt.ClientInterface).Reject(e, messageHash)
						return nil
					}(this)
				}
			}()
			// try block:
			this.HandleErrors(code, error, client.(ccxt.ClientInterface).GetUrl(), "", map[string]any{}, error, message, map[string]any{}, map[string]any{})
			return nil
		}(this)

	}
	if !rejected {
		client.(ccxt.ClientInterface).Reject(message, messageHash)
		return true
	}
	return nil
}
func (this *Bitvavo) HandleMessage(client any, message any) {
	//
	//     {
	//         "event": "subscribed",
	//         "subscriptions": {
	//             "book": [ "BTC-EUR" ]
	//         }
	//     }
	//
	//     {
	//         "event": "book",
	//         "market": "BTC-EUR",
	//         "nonce": 36729561,
	//         "bids": [
	//             [ "8513.3", "0" ],
	//             [ '8518.8', "0.64236203" ],
	//             [ '8513.6', "0.32435481" ],
	//         ],
	//         "asks": []
	//     }
	//
	//     {
	//         "action": "getBook",
	//         "response": {
	//             "market": "BTC-EUR",
	//             "nonce": 36946120,
	//             "bids": [
	//                 [ '8494.9', "0.24399521" ],
	//                 [ '8494.8', "0.34884085" ],
	//                 [ '8493.9', "0.14535128" ],
	//             ],
	//             "asks": [
	//                 [ "8495", "0.46982463" ],
	//                 [ '8495.1', "0.12178267" ],
	//                 [ '8496.2', "0.21924143" ],
	//             ]
	//         }
	//     }
	//
	//     {
	//         "event": "authenticate",
	//         "authenticated": true
	//     }
	//
	var error *string = this.SafeString(message, "error")
	if error != nil {
		this.HandleErrorMessage(client, message)
	}
	var methods map[string]any = map[string]any{
		"subscribed":                  this.HandleSubscriptionStatus,
		"unsubscribed":                this.HandleUnsubscriptionStatus,
		"book":                        this.HandleOrderBook,
		"getBook":                     this.HandleOrderBookSnapshot,
		"trade":                       this.HandleTrade,
		"candle":                      this.HandleOHLCV,
		"ticker24h":                   this.HandleTicker,
		"authenticate":                this.HandleAuthenticationMessage,
		"order":                       this.HandleOrder,
		"fill":                        this.HandleMyTrade,
		"privateCreateOrder":          this.HandleSingleOrder,
		"privateUpdateOrder":          this.HandleSingleOrder,
		"privateGetBalance":           this.HandleFetchBalance,
		"privateCancelOrders":         this.HandleMultipleOrders,
		"privateGetOrders":            this.HandleMultipleOrders,
		"privateGetOrder":             this.HandleSingleOrder,
		"privateCancelOrder":          this.HandleSingleOrder,
		"privateGetOrdersOpen":        this.HandleMultipleOrders,
		"privateGetAccount":           this.HandleTradingFees,
		"privateGetDepositHistory":    this.HandleDeposits,
		"privateGetWithdrawalHistory": this.HandleWithdraws,
		"privateWithdrawAssets":       this.HandleWithdraw,
		"privateGetTrades":            this.HandleMyTrades,
		"getAssets":                   this.HandleFetchCurrencies,
		"getCandles":                  this.HandleFetchOHLCV,
		"getMarkets":                  this.HandleMarkets,
	}
	var event *string = this.SafeString(message, "event")
	var method any = this.SafeValue(methods, event)
	if ccxt.IsEqual(method, nil) {
		var action *string = this.SafeString(message, "action")
		method = this.SafeValue(methods, action)
		if !ccxt.IsEqual(method, nil) {
			ccxt.CallDynamically(method, client, message)
		}
	} else {
		ccxt.CallDynamically(method, client, message)
	}
}

